package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// API53 exact successor of all sixteen Salesforce Wave92 observation rows.
func TestRunCallerVisibilityContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeCallerVisibility53.cls"), "@IsTest private class GladeCallerVisibility53 {\n private static Map<String,Object> readField(String phase,SObject record,String field){\n  Map<String,Object> row=new Map<String,Object>{'phase'=>phase,'field'=>field};\n  try{row.put('value',record.get(field));}catch(Exception e){row.put('type',e.getTypeName());row.put('message',e.getMessage());}\n  return row;\n }\n private static Map<String,Object> readClosed(String phase,Task record){\n  Map<String,Object> row=new Map<String,Object>{'phase'=>phase,'field'=>'IsClosed'};\n  try{row.put('value',record.IsClosed);}catch(Exception e){row.put('type',e.getTypeName());row.put('message',e.getMessage());}\n  return row;\n }\n private static void assertObserved(Object expected,Object actual,String label){\n  if(expected instanceof Map<String,Object>){\n   System.assert(actual instanceof Map<String,Object>,label+': map type');\n   Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n   System.assertEquals(want.keySet(),got.keySet(),label+': exact fields');\n   for(String key:want.keySet())assertObserved(want.get(key),got.get(key),label+'.'+key);\n  }else if(expected instanceof List<Object>){\n   System.assert(actual instanceof List<Object>,label+': list type');\n   List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n   System.assertEquals(want.size(),got.size(),label+': exact size');\n   for(Integer i=0;i<want.size();i++)assertObserved(want[i],got[i],label+'['+i+']');\n  }else{\n   System.assertEquals(expected,actual,label);\n   if(expected instanceof String)System.assert(((String)expected).equals((String)actual),label+': exact text');\n  }\n }\n private static void finish(String method,List<Object> rows,Integer count){\n  System.assertEquals(count,rows.size(),method+': complete rows');\n  String payload=JSON.serialize(new Map<String,Object>{'done'=>true,'method'=>method,'rows'=>rows});\n  System.assert(payload.length()<2900,method+': complete output bound');\n  Map<String,String> expectedByMethod=new Map<String,String>{'contactProjectionAndFresh'=>'{\"rows\":[{\"value\":null,\"field\":\"Salutation\",\"phase\":\"freshBefore\"},{\"value\":null,\"field\":\"Salutation\",\"phase\":\"freshAfter\"},{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: Contact.Salutation\",\"type\":\"System.SObjectException\",\"field\":\"Salutation\",\"phase\":\"queriedBefore\"},{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: Contact.Salutation\",\"type\":\"System.SObjectException\",\"field\":\"Salutation\",\"phase\":\"queriedAfter\"},{\"value\":null,\"field\":\"Salutation\",\"phase\":\"sparseBefore\"},{\"value\":null,\"field\":\"Salutation\",\"phase\":\"sparseAfter\"}],\"method\":\"contactProjectionAndFresh\",\"done\":true}','taskProjectionAndFresh'=>'{\"rows\":[{\"value\":false,\"field\":\"IsClosed\",\"phase\":\"freshBefore\"},{\"value\":false,\"field\":\"IsClosed\",\"phase\":\"freshAfter\"},{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: Task.IsClosed\",\"type\":\"System.SObjectException\",\"field\":\"IsClosed\",\"phase\":\"queriedBefore\"},{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: Task.Subject\",\"type\":\"System.SObjectException\",\"field\":\"Subject\",\"phase\":\"queriedBefore\"},{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: Task.IsClosed\",\"type\":\"System.SObjectException\",\"field\":\"IsClosed\",\"phase\":\"queriedAfter\"},{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: Task.Subject\",\"type\":\"System.SObjectException\",\"field\":\"Subject\",\"phase\":\"queriedAfter\"},{\"value\":false,\"field\":\"IsClosed\",\"phase\":\"sparseBefore\"},{\"value\":null,\"field\":\"Subject\",\"phase\":\"sparseBefore\"},{\"value\":false,\"field\":\"IsClosed\",\"phase\":\"sparseAfter\"},{\"value\":null,\"field\":\"Subject\",\"phase\":\"sparseAfter\"}],\"method\":\"taskProjectionAndFresh\",\"done\":true}'};\n  System.assert(expectedByMethod.containsKey(method),method+': expected case');\n  assertObserved(JSON.deserializeUntyped(expectedByMethod.get(method)),JSON.deserializeUntyped(payload),method);\n }\n @IsTest static void contactProjectionAndFresh(){\n  List<Object> rows=new List<Object>();Contact fresh=new Contact(LastName='Owned Caller Visibility');\n  rows.add(readField('freshBefore',fresh,'Salutation'));insert fresh;\n  rows.add(readField('freshAfter',fresh,'Salutation'));\n  Contact selected=[SELECT Id FROM Contact WHERE Id=:fresh.Id];\n  rows.add(readField('queriedBefore',selected,'Salutation'));update selected;\n  rows.add(readField('queriedAfter',selected,'Salutation'));\n  Contact sparse=new Contact(Id=fresh.Id);\n  rows.add(readField('sparseBefore',sparse,'Salutation'));update sparse;\n  rows.add(readField('sparseAfter',sparse,'Salutation'));\n  System.assertEquals('Owned Caller Visibility',[SELECT LastName FROM Contact WHERE Id=:fresh.Id].LastName,'updates preserve stored LastName');\n  finish('contactProjectionAndFresh',rows,6);\n }\n @IsTest static void taskProjectionAndFresh(){\n  List<Object> rows=new List<Object>();\n  List<TaskStatus> opens=[SELECT MasterLabel FROM TaskStatus WHERE IsClosed=false];\n  List<TaskStatus> closeds=[SELECT MasterLabel FROM TaskStatus WHERE IsClosed=true];\n  System.assert(!opens.isEmpty()&&!closeds.isEmpty(),'required TaskStatus population');\n  Task fresh=new Task(Subject='Owned Caller Visibility',Status=opens[0].MasterLabel);\n  rows.add(readClosed('freshBefore',fresh));insert fresh;rows.add(readClosed('freshAfter',fresh));\n  Task selected=[SELECT Id,Status FROM Task WHERE Id=:fresh.Id];\n  rows.add(readClosed('queriedBefore',selected));rows.add(readField('queriedBefore',selected,'Subject'));\n  selected.Status=closeds[0].MasterLabel;update selected;\n  Map<String,Object> postClosed=readClosed('queriedAfter',selected);rows.add(postClosed);\n  System.assertEquals('System.SObjectException',postClosed.get('type'),'previously admitted omitted IsClosed after update type');\n  System.assertEquals('SObject row was retrieved via SOQL without querying the requested field: Task.IsClosed',postClosed.get('message'),'previously admitted omitted IsClosed after update message');\n  rows.add(readField('queriedAfter',selected,'Subject'));\n  System.assertEquals(true,[SELECT IsClosed FROM Task WHERE Id=:fresh.Id].IsClosed,'stored closed effect');\n  Task sparse=new Task(Id=fresh.Id,Status=opens[0].MasterLabel);\n  rows.add(readClosed('sparseBefore',sparse));rows.add(readField('sparseBefore',sparse,'Subject'));\n  update sparse;rows.add(readClosed('sparseAfter',sparse));rows.add(readField('sparseAfter',sparse,'Subject'));\n  Task stored=[SELECT Subject,IsClosed FROM Task WHERE Id=:fresh.Id];\n  System.assertEquals('Owned Caller Visibility',stored.Subject,'sparse update preserves stored Subject');\n  System.assertEquals(false,stored.IsClosed,'stored reopen effect');\n  finish('taskProjectionAndFresh',rows,10);\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeCallerVisibility53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 2 || got.Passed != 2 || got.Failed != 0 || got.Errors != 0 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("caller visibility contracts: %s", data)
	}
}
